previewCss:
.darma-loader-darma-b11-umbrella-open { --accent: var(--loader-color, #f43f5e); --accent-2: var(--loader-secondary-color, #3b82f6); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b11-umbrella-open span { width: 62%; height: 31%; background: conic-gradient(from 270deg at 50% 100%, var(--accent) 0 60deg, var(--accent-2) 60deg 120deg, var(--accent) 120deg 180deg); border-radius: 100% 100% 8px 8px / 100% 100% 8px 8px; transform-origin: 50% 100%; margin-bottom: 30%; animation: darma-loader-darma-b11-umbrella-open-umbrella calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-darma-b11-umbrella-open::after { content: ''; position: absolute; left: 50%; top: 42%; width: calc(var(--loader-size, 84px) * .03); height: calc(var(--loader-size, 84px) * .36); margin-left: calc(var(--loader-size, 84px) * -.015); background: color-mix(in srgb, #000 25%, var(--accent)); border-bottom-left-radius: 8px; border-bottom: calc(var(--loader-size, 84px) * .03) solid color-mix(in srgb, #000 25%, var(--accent)); }
@keyframes darma-loader-darma-b11-umbrella-open-umbrella { 0%, 100% { transform: scale(.32, .28); } 50% { transform: scale(1, 1); } }

